package com.ruoyi.medical.persistence;
import com.ruoyi.medical.workflow.*;
import com.ruoyi.medical.workflow.TaskCandidateAssemblyStageProtocolV1.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.util.function.ThrowingSupplier;
import static com.ruoyi.medical.persistence.TaskRunActivityJournal.*;
/** Deterministic host dispatch. Recovery never calls produce or writes stage journals. */
public record TaskCandidateAssemblyStageEndpointFactory(TaskRunActivityPreparation runs,TaskCandidateAssemblyAuthority inputs,TaskCandidateAssemblyCrossFileAuthority crossFiles,TaskCandidateAssemblyArtifactProduction production,TaskCandidateAssemblyOriginalReader originals,TaskCandidateAssemblyStageJournal stages,FormalRunRecoveryAccess recovery,TaskRunLaunchRecoveryAuthority launches,TaskRunWorkflowLedger workflow,TaskRunWorkflowProtocolBinding protocols,TaskDeterministicExecution executions){
 public TaskCandidateAssemblyStageActivitiesV1 create(HttpServletRequest http){return new TaskCandidateAssemblyStageActivitiesV1(){
  public PreparedV1 prepare(WorkflowProtocol.Reference ref){return ThrowingSupplier.of(()->{verify(http,ref);var saved=recovery.execute(http,ref.tenantId(),ref.runId(),a->ThrowingSupplier.of(()->stages.preparedOriginal(a,ref)).get());if(saved.isPresent())return saved.get();try(var owned=runs.withCurrent(http,ref,c->executions.enter(c,"N06",derived(ref.runId(),"N06_PREPARE")))){var cross=crossFiles.read(http,ref);return runs.withCurrent(http,ref,c->stages.prepare(ref,inputs.require(c,cross)));}}).get();}
  public ProducedV1 dispatch(WorkflowProtocol.Reference ref,CommandV1 command){return ThrowingSupplier.of(()->{command.require(ref);verify(http,ref);try(var owned=runs.withCurrent(http,ref,c->executions.enter(c,"N06",command.commandId()))){var cross=crossFiles.read(http,ref);runs.withCurrent(http,ref,c->{stages.dispatch(ref,command,inputs.require(c,cross));return null;});return production.produce(http,ref,(c,i,objects)->stages.produced(ref,command,i,objects,true));}}).get();}
  public CommitV1 commit(WorkflowProtocol.Reference ref,ProducedV1 produced){return ThrowingSupplier.of(()->{produced.require(ref);verify(http,ref);var old=originals.recover(http,ref,produced.command(),(original,family)->{same(produced,stages.recovered(original,family));return stages.committed(original.admission(),ref,produced.command());});if(old.isPresent())return old.get();try(var owned=runs.withCurrent(http,ref,c->executions.enter(c,"N06",derived(produced.command().commandId(),"N06_COMMIT")))){return production.recover(http,ref,(c,i,objects)->stages.commit(ref,produced,i,objects));}}).get();}
  public RecoveryV1 recover(WorkflowProtocol.Reference ref,CommandV1 command){return ThrowingSupplier.of(()->{command.require(ref);verify(http,ref);var saved=recovery.execute(http,ref.tenantId(),ref.runId(),a->ThrowingSupplier.of(()->stages.command(a,ref)).get());if(saved.isEmpty())return new RecoveryV1("1.0.0","PENDING",command,null,null);same(command,saved.get());
   return originals.recover(http,ref,command,(original,family)->{var produced=stages.recovered(original,family);var committed=stages.committed(original.admission(),ref,command);if(committed.isPresent()){same(produced,committed.get().produced());return new RecoveryV1("1.0.0","COMMITTED",command,produced,committed.get());}return new RecoveryV1("1.0.0","PRODUCED",command,produced,null);});
  }).get();}
 };}
 private void verify(HttpServletRequest http,WorkflowProtocol.Reference ref){recovery.execute(http,ref.tenantId(),ref.runId(),a->ThrowingSupplier.of(()->{var p=launches.require(a,http,ref.runId(),a.recoveryProof().identity().commandId());same(ref,workflow.recover(p).reference());if(workflow.read(p).isEmpty())throw new TenantAccessException(com.ruoyi.medical.contracts.ErrorCode.DEPENDENCY_UNAVAILABLE);protocols.assemblies().requireAccepted(a,ref.runId()).requireUnchanged();p.requireUnchanged();return null;}).get());}
}
